--- a/node/safe-merge/index.mjs
+++ b/node/safe-merge/index.mjs
@@ -1,3 +1,54 @@
+const BLOCKED_KEYS = new Set(["__proto__", "prototype", "constructor"]);
+
+function isPlainObject(value) {
+  if (typeof value !== "object" || value === null) return false;
+  if (Array.isArray(value)) return false;
+  if (value instanceof Date) return false;
+  const proto = Object.getPrototypeOf(value);
+  return proto === Object.prototype || proto === null;
+}
+
+function safeKeys(obj) {
+  return Object.keys(obj).filter((key) => !BLOCKED_KEYS.has(key));
+}
+
+function deepClone(value) {
+  if (value === null || typeof value !== "object") return value;
+  if (value instanceof Date) return new Date(value.getTime());
+  if (Array.isArray(value)) return value.map(deepClone);
+
+  // Plain objects (including null-prototype) and class instances: preserve
+  // the prototype and deep-clone own enumerable, non-blocked properties.
+  const proto = Object.getPrototypeOf(value);
+  const result = Object.create(proto);
+  for (const key of safeKeys(value)) {
+    result[key] = deepClone(value[key]);
+  }
+  return result;
+}
+
 export function safeMerge(base, patch) {
-  return { ...base, ...patch };
+  const baseKeys = new Set(isPlainObject(base) ? safeKeys(base) : []);
+  const patchKeys = new Set(isPlainObject(patch) ? safeKeys(patch) : []);
+  const allKeys = new Set([...baseKeys, ...patchKeys]);
+
+  const result = {};
+  for (const key of allKeys) {
+    const hasBase = baseKeys.has(key);
+    const hasPatch = patchKeys.has(key);
+
+    if (hasBase && hasPatch) {
+      const baseValue = base[key];
+      const patchValue = patch[key];
+      result[key] =
+        isPlainObject(baseValue) && isPlainObject(patchValue)
+          ? safeMerge(baseValue, patchValue)
+          : deepClone(patchValue);
+    } else if (hasPatch) {
+      result[key] = deepClone(patch[key]);
+    } else {
+      result[key] = deepClone(base[key]);
+    }
+  }
+  return result;
 }
